/* --- 1. FONT IMPORT --- */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

/* --- 2. CSS VARIABLES (THE PALETTE) --- */
:root {
  /* Light Mode Colors */
  --bg-primary: #f8f9fa;
  --bg-secondary: #ffffff;
  --bg-tertiary: #e9ecef;
  --text-primary: #212529;
  --text-secondary: #495057;
  --text-muted: #6c757d;
  --border-color: #dee2e6;
  --primary-color: #007bff;
  --primary-color-dark: #0056b3;
  --text-on-primary: #ffffff;
  --color-correct: #28a745;
  --color-incorrect: #dc3545;
  
  /* Transparent Colors for Background Image Effect (NEW) */
  --bg-secondary-transparent: rgba(255, 255, 255, 0.85); /* 85% white for light mode cards */
  
  /* Shadows & Radius */
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 10px rgba(0, 0, 0, 0.05);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 999px;
}

body.dark {
  /* Dark Mode Colors */
  --bg-primary: #121212;
  --bg-secondary: #1e1e1e;
  --bg-tertiary: #2a2a2a;
  --text-primary: #e0e0e0;
  --text-secondary: #adb5bd;
  --text-muted: #6c757d;
  --border-color: #3a3a3a;
  --primary-color: #0d6efd;
  --primary-color-dark: #0b5ed7;
  --color-correct: #28a745;
  --color-incorrect: #dc3545;

  /* Transparent Colors for Background Image Effect (NEW) */
  --bg-secondary-transparent: rgba(30, 30, 30, 0.8); /* 80% dark gray for dark mode cards */
}

/* --- 3. GLOBAL RESET & BODY --- */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  /* --- BACKGROUND IMAGE APPLIED HERE --- */
  background-image: url("data:image/png;base64,");
  background-size: cover; 
  background-repeat: no-repeat;
  background-attachment: fixed; /* Fixes the image relative to the viewport */
  background-position: center center;
  /* We remove background: var(--bg-primary); to let the image show */
  
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text-primary);
  /* We only transition color, not background */
  transition: color 0.3s ease;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}


/* --- BACKGROUND OVERLAY (For Readability) --- */
/* This creates a semi-transparent layer over the image to ensure text pops */
body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    /* Subtle dark overlay */
    background: rgba(0, 0, 0, 0.25); 
    z-index: -1; /* Place behind all content */
    transition: background 0.3s ease;
}

/* Adjust overlay for dark mode */
body.dark::before {
    background: rgba(0, 0, 0, 0.4); 
}

/* --- 4. HEADER & THEME TOGGLE --- */
header {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(5px); /* Add a modern blur effect */
  border-bottom: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 100;
}


/* Style for the theme toggle button */
#themeToggle {
  font-size: 1.5rem;
  background: none;
  border: none;
  border-radius: var(--radius-full);
  padding: 0.5rem;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-secondary);
  transition: all 0.2s ease;
}

#themeToggle:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

/* --- 5. NAVIGATION --- */
nav {
  display: flex;
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(5px); /* Add a modern blur effect */
  border-bottom: 1px solid var(--border-color);
  padding: 0.5rem;
  gap: 0.5rem;
  overflow-x: auto; /* For mobile */
}

nav button {
  flex: 1;
  padding: 0.75rem 1rem;
  border: none;
  background: none;
  cursor: pointer;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.2s ease;
  white-space: nowrap; /* Prevent wrapping */
}

nav button:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

nav button.active {
  background: var(--primary-color);
  color: var(--text-on-primary);
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

/* --- 6. MAIN APP CONTAINER --- */
#app {
  padding: 1rem 1rem 4rem 1rem; /* Added bottom padding */
  max-width: 800px;
  margin: 0 auto;
}

/* --- 7. GENERIC FORMS (Inputs, Buttons) --- */
input[type="text"],
input[type="number"],
select {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(3px);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.25);
}

button {
  cursor: pointer;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all 0.2s ease;
}

/* Primary button style (e.g., Load Chapter, Search) */
#loadChapter, #searchBtn {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  background: var(--primary-color);
  color: var(--text-on-primary);
  border: none;
}

#loadChapter:hover, #searchBtn:hover {
  background: var(--primary-color-dark);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

/* --- 8. READER VIEW --- */
.reader-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}
.reader-controls select { flex: 3 1 200px; }
.reader-controls input { flex: 1 1 80px; }
.reader-controls button { flex: 1 1 120px; }

.verse {
  margin: 0.5rem 0;
  padding: 1rem;
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(3px);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  line-height: 1.7;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.verse-num {
  font-weight: 700;
  color: var(--primary-color);
  opacity: 0.8;
  font-size: 0.9rem;
  padding-top: 0.1rem;
}

.bookmark-btn {
  background: none;
  border: none;
  font-size: 1.3rem;
  color: var(--text-muted);
  transition: all 0.2s ease;
  align-self: flex-start;
}

.bookmark-btn:hover {
  color: var(--primary-color);
  transform: scale(1.2);
}

.bookmark-btn[disabled],
.bookmark-btn:disabled {
  color: #f0c419; /* Gold for saved */
  transform: none;
  cursor: default;
}

/* --- 9. QUIZ VIEW --- */
.quiz button.option {
  display: block;
  width: 100%;
  margin: 0.5rem 0;
  padding: 1rem;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(3px);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
  transition: all 0.2s ease;
}

.quiz button.option:not(:disabled):hover {
  border-color: var(--primary-color);
  background: var(--bg-tertiary);
  transform: translateX(5px);
}

.correct {
  background: var(--color-correct) !important;
  border-color: var(--color-correct) !important;
  color: white !important;
  font-weight: 700;
}

.incorrect {
  background: var(--color-incorrect) !important;
  border-color: var(--color-incorrect) !important;
  color: white !important;
  font-weight: 700;
}

/* --- 10. BOOKMARKS & SEARCH RESULTS --- */
.search-view {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
}
.search-view input { flex: 1 1 300px; }
.search-view button { flex: 0 1 auto; }

#searchResults, .bookmarks-list {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

/* Card for bookmarks and search results */
.bookmark,
#searchResults p {
  background: var(--bg-secondary-transparent); /* Updated to translucent */
  backdrop-filter: blur(3px);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  border-left: 4px solid var(--primary-color);
  box-shadow: var(--shadow-sm);
  line-height: 1.6;
}

#searchResults p strong {
  color: var(--primary-color);
  display: block; /* Makes it stack */
  margin-bottom: 0.25rem;
}

.bookmark strong {
  font-size: 1.1rem;
  color: var(--primary-color);
}
.bookmark p { margin-bottom: 0.25rem; }
.bookmark small {
  color: var(--text-muted);
  font-style: italic;
}

/* --- 11. RESPONSIVE --- */
@media (max-width: 600px) {
  nav {
    flex-direction: row; /* Keep as row but make it scrollable */
    justify-content: flex-start;
    padding: 0.5rem;
  }
  
  nav button {
    flex: 0 0 auto; /* Don't stretch, let them be their own size */
  }

  /* Stack reader/search controls */
  .reader-controls, .search-view {
    flex-direction: column;
  }
}